content:
name: publish

on:
  workflow_run:
    workflows:
      - release candidate
    types:
      - completed

concurrency:
  group: npm-publish
  cancel-in-progress: false

permissions: {}

jobs:
  verify:
    name: verify release candidate
    if: github.repository == 'approval-md/approval.md'
    runs-on: ubuntu-24.04
    timeout-minutes: 45
    permissions:
      contents: read
    outputs:
      artifact_digest: ${{ steps.release_artifact.outputs['artifact-digest'] }}
      release_sha256: ${{ steps.release_hash.outputs.sha256 }}
    steps:
      - name: Verify workflow-run metadata
        env:
          DOWNSTREAM_EVENT: ${{ github.event_name }}
          DOWNSTREAM_REPOSITORY: ${{ github.repository }}
          RELEASE_CONCLUSION: ${{ github.event.workflow_run.conclusion }}
          RELEASE_EVENT: ${{ github.event.workflow_run.event }}
          RELEASE_HEAD_REPOSITORY: ${{ github.event.workflow_run.head_repository.full_name }}
          RELEASE_RUN_ATTEMPT: ${{ github.event.workflow_run.run_attempt }}
          RELEASE_SHA: ${{ github.event.workflow_run.head_sha }}
          RELEASE_TAG: ${{ github.event.workflow_run.head_branch }}
          RELEASE_WORKFLOW_NAME: ${{ github.event.workflow_run.name }}
          RELEASE_WORKFLOW_PATH: ${{ github.event.workflow_run.path }}
        run: |
          node --input-type=module <<'NODE'
          const expected = new Map([
            ['DOWNSTREAM_EVENT', 'workflow_run'],
            ['DOWNSTREAM_REPOSITORY', 'approval-md/approval.md'],
            ['RELEASE_CONCLUSION', 'success'],
            ['RELEASE_EVENT', 'push'],
            ['RELEASE_HEAD_REPOSITORY', 'approval-md/approval.md'],
            ['RELEASE_RUN_ATTEMPT', '1'],
            ['RELEASE_WORKFLOW_NAME', 'release candidate'],
            ['RELEASE_WORKFLOW_PATH', '.github/workflows/release-candidate.yml'],
          ]);
          for (const [name, wanted] of expected) {
            if (process.env[name] !== wanted) {
              throw new Error(`${name} must be ${JSON.stringify(wanted)}`);
            }
          }
          const stable = /^v(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u;
          if (!stable.test(process.env.RELEASE_TAG ?? '')) {
            throw new Error('RELEASE_TAG must be a canonical stable vX.Y.Z tag');
          }
          if (!/^[0-9a-f]{40}$/u.test(process.env.RELEASE_SHA ?? '')) {
            throw new Error('RELEASE_SHA must be a full lowercase commit SHA');
          }
          NODE

      - uses: actions/checkout@df4cb1c069e1874edd31b4311f1884172cec0e10 # v6.0.3
        with:
          fetch-depth: 1
          fetch-tags: false
          persist-credentials: false
          ref: ${{ github.sha }}

      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6.5.0
        with:
          node-version: '24'
          package-manager-cache: false

      - name: Bind tag, event, checkout, and current main
        env:
          DOWNSTREAM_REF: ${{ github.ref }}
          DOWNSTREAM_SHA: ${{ github.sha }}
          RELEASE_SHA: ${{ github.event.workflow_run.head_sha }}
          RELEASE_TAG: ${{ github.event.workflow_run.head_branch }}
        run: |
          set -euo pipefail
          node --input-type=module <<'NODE'
          const stable = /^v(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u;
          for (const name of ['DOWNSTREAM_SHA', 'RELEASE_SHA']) {
            if (!/^[0-9a-f]{40}$/u.test(process.env[name] ?? '')) {
              throw new Error(`${name} must be a full lowercase commit SHA`);
            }
          }
          if (process.env.DOWNSTREAM_REF !== 'refs/heads/main') {
            throw new Error('publisher workflow must run from refs/heads/main');
          }
          if (!stable.test(process.env.RELEASE_TAG ?? '')) {
            throw new Error('RELEASE_TAG must be a canonical stable vX.Y.Z tag');
          }
          NODE

          git fetch --no-tags origin '+refs/heads/main:refs/remotes/origin/main'
          git fetch --no-tags origin "refs/tags/${RELEASE_TAG}:refs/tags/${RELEASE_TAG}"

          checkout_sha="$(git rev-parse 'HEAD^{commit}')"
          current_main_sha="$(git rev-parse 'refs/remotes/origin/main^{commit}')"
          tag_sha="$(git rev-parse "refs/tags/${RELEASE_TAG}^{commit}")"
          test "$tag_sha" = "$RELEASE_SHA"
          test "$RELEASE_SHA" = "$DOWNSTREAM_SHA"
          test "$DOWNSTREAM_SHA" = "$checkout_sha"
          test "$checkout_sha" = "$current_main_sha"

      - name: Verify package and tool identity
        env:
          RELEASE_TAG: ${{ github.event.workflow_run.head_branch }}
        run: |
          set -euo pipefail
          npm_version="$(npm --version)"
          NPM_VERSION="$npm_version" node --input-type=module <<'NODE'
          import { readFileSync } from 'node:fs';

          function atLeast(actual, floor) {
            const parse = (value) => {
              if (!/^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u.test(value)) {
                throw new Error(`noncanonical tool version ${JSON.stringify(value)}`);
              }
              return value.split('.').map(Number);
            };
            const left = parse(actual);
            const right = parse(floor);
            for (let index = 0; index < left.length; index += 1) {
              if (left[index] > right[index]) return true;
              if (left[index] < right[index]) return false;
            }
            return true;
          }

          const manifest = JSON.parse(readFileSync('package.json', 'utf8'));
          const version = (process.env.RELEASE_TAG ?? '').slice(1);
          if (manifest.name !== 'approval-md') throw new Error('package name must be approval-md');
          if (manifest.version !== version) throw new Error('package version must equal the release tag');
          if (manifest.private === true) throw new Error('package must be public');
          if (manifest.repository !== 'github:approval-md/approval.md') {
            throw new Error('package repository must be github:approval-md/approval.md');
          }
          if (!atLeast(process.versions.node, '22.14.0')) throw new Error('Node must be at least 22.14.0');
          if (!atLeast(process.env.NPM_VERSION ?? '', '11.5.1')) throw new Error('npm must be at least 11.5.1');
          NODE

      - name: Install locked dependencies
        run: npm ci

      - name: Run full test suite
        run: npm test

      - name: Run lint
        run: npm run lint

      - name: Run typecheck
        run: npm run typecheck

      - name: Run conformance suite
        run: npm run conformance

      - name: Pack and verify release bytes
        env:
          RELEASE_TAG: ${{ github.event.workflow_run.head_branch }}
        run: |
          set -euo pipefail
          out="$RUNNER_TEMP/npm-package"
          mkdir -p "$out"
          npm pack --json --pack-destination "$out" > "$out/pack.json"

          PACK_JSON="$out/pack.json" node --input-type=module <<'NODE'
          import { readFileSync } from 'node:fs';
          const packed = JSON.parse(readFileSync(process.env.PACK_JSON, 'utf8'));
          const version = (process.env.RELEASE_TAG ?? '').slice(1);
          const filename = `approval-md-${version}.tgz`;
          if (!Array.isArray(packed) || packed.length !== 1) throw new Error('npm pack must emit exactly one package');
          if (packed[0]?.name !== 'approval-md') throw new Error('packed name must be approval-md');
          if (packed[0]?.version !== version) throw new Error('packed version must equal the release tag');
          if (packed[0]?.filename !== filename) throw new Error('packed filename is not canonical');
          NODE

          version="${RELEASE_TAG#v}"
          mv "$out/approval-md-${version}.tgz" "$out/release.tgz"
          tar -xOf "$out/release.tgz" package/package.json > "$out/packed-package.json"
          PACKED_MANIFEST="$out/packed-package.json" node --input-type=module <<'NODE'
          import { readFileSync } from 'node:fs';
          const manifest = JSON.parse(readFileSync(process.env.PACKED_MANIFEST, 'utf8'));
          const version = (process.env.RELEASE_TAG ?? '').slice(1);
          if (manifest.name !== 'approval-md') throw new Error('tarball package name must be approval-md');
          if (manifest.version !== version) throw new Error('tarball package version must equal the release tag');
          if (manifest.private === true) throw new Error('tarball package must be public');
          if (manifest.repository !== 'github:approval-md/approval.md') {
            throw new Error('tarball repository must be github:approval-md/approval.md');
          }
          NODE
          (
            cd "$out"
            sha256sum release.tgz > release.tgz.sha256
            sha256sum --check --strict release.tgz.sha256
          )

      - id: release_hash
        name: Bind release SHA-256 outside the artifact
        run: |
          set -euo pipefail
          digest="$(sha256sum "$RUNNER_TEMP/npm-package/release.tgz" | cut -d ' ' -f 1)"
          case "$digest" in
            *[!0-9a-f]*|'') exit 1 ;;
          esac
          test "${#digest}" -eq 64
          echo "sha256=$digest" >> "$GITHUB_OUTPUT"

      - id: release_artifact
        name: Upload fixed release artifact
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: npm-package
          path: ${{ runner.temp }}/npm-package/release.tgz
          if-no-files-found: error
          retention-days: 1
          compression-level: 0

  publish:
    name: publish to npm
    needs: verify
    if: needs.verify.outputs.artifact_digest != '' && needs.verify.outputs.release_sha256 != ''
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    environment: npm
    permissions:
      id-token: write
    steps:
      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6.5.0
        with:
          node-version: '24'
          registry-url: https://registry.npmjs.org
          package-manager-cache: false

      - name: Download artifact from this workflow run
        uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: npm-package
          path: ${{ runner.temp }}/release

      - name: Verify and publish fixed artifact
        working-directory: ${{ runner.temp }}
        env:
          EXPECTED_SHA256: ${{ needs.verify.outputs.release_sha256 }}
        run: |
          set -euo pipefail
          case "$EXPECTED_SHA256" in
            *[!0-9a-f]*|'') exit 1 ;;
          esac
          test "${#EXPECTED_SHA256}" -eq 64
          actual_sha256="$(sha256sum ./release/release.tgz | cut -d ' ' -f 1)"
          test "$actual_sha256" = "$EXPECTED_SHA256"
          npm publish ./release/release.tgz --access public --ignore-scripts
